import math
import re

SCRIPT_ID = "hearth_companion_py"
STAGES = ("Stranger", "Trusted", "Bonded")
STAGE_ORDER = {"Stranger": 0, "Trusted": 1, "Bonded": 2}
PORTRAITS = {
    "Stranger": "https://example.com/portraits/lyra_stranger.webp",
    "Trusted": "https://example.com/portraits/lyra_trusted.webp",
    "Bonded": "https://example.com/portraits/lyra_bonded.webp",
}
COMFORT_EFFECTS = {
    "words": (4, 5, "Reassured Lyra with quiet, steady words."),
    "embrace": (8, 7, "Held Lyra close beside the hearthfire."),
    "gift": (6, 10, "Offered Lyra a thoughtful keepsake by the fire."),
}


def _to_float(value, default=0.0):
    try:
        num = float(value)
        if not math.isfinite(num):
            return default
        return num
    except (TypeError, ValueError):
        return default


def _clamp(value, min_val=0, max_val=100):
    num = _to_float(value, float(min_val))
    return max(min_val, min(max_val, int(round(num))))


def _normalize_comfort_kind(raw):
    token = re.sub(r"\s+", " ", str(raw or "").strip().lower())
    if token in COMFORT_EFFECTS:
        return token
    if token in ("word", "talk", "speak", "reassure"):
        return "words"
    if token in ("hug", "hold", "cuddle"):
        return "embrace"
    if token in ("present", "keepsake", "token"):
        return "gift"
    return ""


def init_state(ctx):
    return {
        "name": "Lyra",
        "stage": "Stranger",
        "warmth": 45,
        "trust": 10,
        "day": 1,
        "cared_today": False,
        "neglect_days": 0,
        "shown_images": [],
    }


def ensure_state_shape(raw):
    base = init_state({})
    if isinstance(raw, dict):
        for key, val in raw.items():
            if key in base:
                base[key] = val

    name = re.sub(r"\s+", " ", str(base.get("name") or "Lyra").strip())[:48]
    stage = str(base.get("stage") or "Stranger").strip()
    if stage not in STAGE_ORDER:
        stage = "Stranger"

    shown = []
    raw_shown = base.get("shown_images")
    if isinstance(raw_shown, list):
        for item in raw_shown:
            url = str(item or "").strip()
            if url and url not in shown:
                shown.append(url)

    return {
        "name": name or "Lyra",
        "stage": stage,
        "warmth": _clamp(base.get("warmth", 45), 0, 100),
        "trust": _clamp(base.get("trust", 10), 0, 100),
        "day": max(1, int(math.floor(_to_float(base.get("day", 1), 1.0)))),
        "cared_today": bool(base.get("cared_today", False)),
        "neglect_days": max(0, int(math.floor(_to_float(base.get("neglect_days", 0), 0.0)))),
        "shown_images": shown,
    }


def evaluate_progression(state):
    prev_stage = state["stage"]
    prev_idx = STAGE_ORDER.get(prev_stage, 0)
    target_idx = prev_idx
    trust = state["trust"]

    if trust >= 35:
        target_idx = max(target_idx, STAGE_ORDER["Trusted"])
    if trust >= 75:
        target_idx = max(target_idx, STAGE_ORDER["Bonded"])

    next_idx = max(prev_idx, target_idx)
    next_stage = STAGES[next_idx]
    state["stage"] = next_stage
    stage_changed = next_idx > prev_idx

    portrait_url = PORTRAITS.get(next_stage, PORTRAITS["Stranger"])
    append_markdown = ""
    if stage_changed and next_stage in ("Trusted", "Bonded"):
        if portrait_url not in state["shown_images"]:
            state["shown_images"] = [*state["shown_images"], portrait_url]
            append_markdown = f"![]({portrait_url})"

    return {
        "stage_changed": stage_changed,
        "prev_stage": prev_stage,
        "next_stage": next_stage,
        "portrait_url": portrait_url,
        "append_markdown": append_markdown,
    }


def apply_day_rollover(state, count=1):
    days = _clamp(count, 1, 30)
    for _ in range(days):
        state["day"] += 1
        if not state["cared_today"]:
            state["neglect_days"] += 1
            state["warmth"] = _clamp(state["warmth"] - 10, 0, 100)
            state["trust"] = _clamp(state["trust"] - 3, 0, 100)
        else:
            state["neglect_days"] = max(0, state["neglect_days"] - 1)
            state["warmth"] = _clamp(state["warmth"] - 5, 0, 100)
        state["cared_today"] = False
    return days


def apply_tend_fire(state, raw_intensity=3):
    intensity = _clamp(raw_intensity if raw_intensity is not None else 3, 1, 5)
    warmth_gain = intensity * 6
    trust_gain = 1 + (intensity // 2)
    state["warmth"] = _clamp(state["warmth"] + warmth_gain, 0, 100)
    state["trust"] = _clamp(state["trust"] + trust_gain, 0, 100)
    state["cared_today"] = True
    state["neglect_days"] = max(0, state["neglect_days"] - 1)
    prog = evaluate_progression(state)
    return {
        "ok": True,
        "intensity": intensity,
        "warmth_gain": warmth_gain,
        "trust_gain": trust_gain,
        "event": (
            f"Tended the hearth fire (intensity {intensity}/5): "
            f"+{warmth_gain} Warmth, +{trust_gain} Trust."
        ),
        "prog": prog,
    }


def apply_comfort(state, raw_kind):
    kind = _normalize_comfort_kind(raw_kind)
    if not kind:
        return {
            "ok": False,
            "error": "Invalid comfort kind. Choose one of: words, embrace, gift.",
        }
    warmth_gain, trust_gain, summary = COMFORT_EFFECTS[kind]
    state["warmth"] = _clamp(state["warmth"] + warmth_gain, 0, 100)
    state["trust"] = _clamp(state["trust"] + trust_gain, 0, 100)
    state["cared_today"] = True
    state["neglect_days"] = max(0, state["neglect_days"] - 1)
    prog = evaluate_progression(state)
    return {
        "ok": True,
        "kind": kind,
        "warmth_gain": warmth_gain,
        "trust_gain": trust_gain,
        "event": f"{summary} (+{warmth_gain} Warmth, +{trust_gain} Trust).",
        "prog": prog,
    }


def apply_set_name(state, raw_name):
    cleaned = re.sub(r'^["\']+|["\']+$', "", str(raw_name or "").strip())
    cleaned = re.sub(r"\s+", " ", cleaned)[:48].strip()
    if not cleaned:
        return {
            "ok": False,
            "error": "Please provide a non-empty name (e.g. !hearth name: Lyra).",
        }
    state["name"] = cleaned
    state["trust"] = _clamp(state["trust"] + 2, 0, 100)
    state["cared_today"] = True
    state["neglect_days"] = max(0, state["neglect_days"] - 1)
    prog = evaluate_progression(state)
    return {
        "ok": True,
        "name": cleaned,
        "event": f"Companion name set to '{cleaned}' (+2 Trust).",
        "prog": prog,
    }


def _build_status_payload(state, prog):
    return {
        "ok": True,
        "name": state["name"],
        "stage": state["stage"],
        "warmth": state["warmth"],
        "trust": state["trust"],
        "day": state["day"],
        "cared_today": state["cared_today"],
        "neglect_days": state["neglect_days"],
        "portrait_url": prog["portrait_url"],
    }


def _build_prompt_injection(state, summary, prog, time_notes=None):
    lines = [f"[SCRIPT_EVENT] {summary}"]
    if time_notes:
        lines.extend(time_notes)
    lines.append(
        f"Authoritative State: Name={state['name']}, Stage={state['stage']}, "
        f"Warmth={state['warmth']}/100, Trust={state['trust']}/100, "
        f"Day={state['day']}, NeglectDays={state['neglect_days']}."
    )
    lines.append(
        "Do NOT re-call Script_HearthCompanion for this already-handled pre-turn command."
    )
    if prog.get("stage_changed"):
        lines.append(
            f"STAGE TRANSITION ({prog['prev_stage']} -> {prog['next_stage']}): "
            "Reflect Lyra's deeper trust and eased posture beside the hearth naturally."
        )
    return "\n".join(lines)


def on_before_generate(state, ctx):
    ctx = ctx if isinstance(ctx, dict) else {}
    s = ensure_state_shape(state)
    time_notes = []

    time_info = ctx.get("time") if isinstance(ctx.get("time"), dict) else {}
    delta_minutes = max(0, int(math.floor(_to_float(time_info.get("deltaMinutes", 0), 0.0))))
    day_changed = bool(time_info.get("dayChanged", False))

    cmd = ctx.get("command") if isinstance(ctx.get("command"), dict) else {}
    sub = str(cmd.get("subcommand") or "").strip().lower()
    raw_args = str(cmd.get("rawArgs") or "").strip()

    if sub == "reset":
        fresh = init_state(ctx)
        prog = evaluate_progression(fresh)
        return {
            "state": fresh,
            "portrait_url": prog["portrait_url"],
            "prompt_injection": _build_prompt_injection(
                fresh, "Hearth Companion state reset to defaults.", prog
            ),
        }

    if delta_minutes > 0:
        decay = delta_minutes // 15
        if decay > 0:
            s["warmth"] = _clamp(s["warmth"] - decay, 0, 100)
            time_notes.append(
                f"[TIME] Elapsed {delta_minutes}m cooled the hearth by -{decay} Warmth (now {s['warmth']}/100)."
            )

    if day_changed:
        prev_day = s["day"]
        apply_day_rollover(s, 1)
        time_notes.append(
            f"[TIME] New day ({prev_day} -> {s['day']}): Warmth {s['warmth']}/100, Trust {s['trust']}/100, Neglect {s['neglect_days']}."
        )

    if not sub:
        prog = evaluate_progression(s)
        out = {"state": s, "portrait_url": prog["portrait_url"]}
        notes = list(time_notes)
        if s["warmth"] <= 20:
            notes.append(
                f"[HEARTH_COMPANION] Warmth is low ({s['warmth']}/100); embers are fading and Lyra shivers."
            )
        if prog["stage_changed"]:
            notes.append(
                f"STAGE TRANSITION ({prog['prev_stage']} -> {prog['next_stage']}): Reflect Lyra's deeper trust naturally."
            )
        if notes:
            out["prompt_injection"] = "\n".join(notes)
        if prog["append_markdown"]:
            out["append_markdown"] = prog["append_markdown"]
        return out

    if sub in ("tend", "tend_fire", "tend-fire"):
        match = re.search(r"-?\d+", raw_args)
        intensity = int(match.group(0)) if match else 3
        res = apply_tend_fire(s, intensity)
        out = {
            "state": s,
            "portrait_url": res["prog"]["portrait_url"],
            "prompt_injection": _build_prompt_injection(s, res["event"], res["prog"], time_notes),
        }
        if res["prog"]["append_markdown"]:
            out["append_markdown"] = res["prog"]["append_markdown"]
        return out

    if sub == "comfort":
        res = apply_comfort(s, raw_args or "words")
        if not res["ok"]:
            prog = evaluate_progression(s)
            return {
                "state": s,
                "portrait_url": prog["portrait_url"],
                "prompt_injection": f"[SCRIPT_EVENT] {res['error']}",
            }
        out = {
            "state": s,
            "portrait_url": res["prog"]["portrait_url"],
            "prompt_injection": _build_prompt_injection(s, res["event"], res["prog"], time_notes),
        }
        if res["prog"]["append_markdown"]:
            out["append_markdown"] = res["prog"]["append_markdown"]
        return out

    if sub == "name":
        res = apply_set_name(s, raw_args)
        if not res["ok"]:
            prog = evaluate_progression(s)
            return {
                "state": s,
                "portrait_url": prog["portrait_url"],
                "prompt_injection": f"[SCRIPT_EVENT] {res['error']}",
            }
        out = {
            "state": s,
            "portrait_url": res["prog"]["portrait_url"],
            "prompt_injection": _build_prompt_injection(s, res["event"], res["prog"], time_notes),
        }
        if res["prog"]["append_markdown"]:
            out["append_markdown"] = res["prog"]["append_markdown"]
        return out

    if sub in ("pass-day", "pass_day"):
        match = re.search(r"\d+", raw_args)
        count = int(match.group(0)) if match else 1
        days = apply_day_rollover(s, count)
        prog = evaluate_progression(s)
        out = {
            "state": s,
            "portrait_url": prog["portrait_url"],
            "prompt_injection": _build_prompt_injection(
                s,
                f"Passed {days} day(s) -> Day {s['day']} (Neglect {s['neglect_days']}).",
                prog,
                time_notes,
            ),
        }
        if prog["append_markdown"]:
            out["append_markdown"] = prog["append_markdown"]
        return out

    if sub == "status":
        prog = evaluate_progression(s)
        return {
            "state": s,
            "portrait_url": prog["portrait_url"],
            "prompt_injection": _build_prompt_injection(
                s, "Inspected Hearth Companion status.", prog, time_notes
            ),
        }

    prog = evaluate_progression(s)
    return {
        "state": s,
        "portrait_url": prog["portrait_url"],
        "prompt_injection": (
            f"[SCRIPT_EVENT] Unknown !hearth command '{sub}'. "
            "Valid commands: tend <1-5>, comfort: <words|embrace|gift>, name: <Name>, pass-day, status, reset."
        ),
    }


def on_tool_call(state, call, ctx):
    s = ensure_state_shape(state)
    call = call if isinstance(call, dict) else {}
    action = str(call.get("action") or "").strip().lower().replace("-", "_")
    args = call.get("args") if isinstance(call.get("args"), dict) else {}

    if action == "status":
        prog = evaluate_progression(s)
        return {
            "state": s,
            "portrait_url": prog["portrait_url"],
            "tool_result": _build_status_payload(s, prog),
        }

    if action == "tend_fire":
        res = apply_tend_fire(s, args.get("intensity", 3))
        out = {
            "state": s,
            "portrait_url": res["prog"]["portrait_url"],
            "tool_result": {
                **_build_status_payload(s, res["prog"]),
                "action": "tend_fire",
                "event": res["event"],
                "stage_changed": res["prog"]["stage_changed"],
            },
        }
        if res["prog"]["append_markdown"]:
            out["append_markdown"] = res["prog"]["append_markdown"]
        return out

    if action == "comfort":
        res = apply_comfort(s, args.get("kind"))
        if not res["ok"]:
            prog = evaluate_progression(s)
            return {
                "state": s,
                "portrait_url": prog["portrait_url"],
                "tool_result": {"ok": False, "error": res["error"]},
            }
        out = {
            "state": s,
            "portrait_url": res["prog"]["portrait_url"],
            "tool_result": {
                **_build_status_payload(s, res["prog"]),
                "action": "comfort",
                "kind": res["kind"],
                "event": res["event"],
                "stage_changed": res["prog"]["stage_changed"],
            },
        }
        if res["prog"]["append_markdown"]:
            out["append_markdown"] = res["prog"]["append_markdown"]
        return out

    if action == "set_name":
        res = apply_set_name(s, args.get("name"))
        if not res["ok"]:
            prog = evaluate_progression(s)
            return {
                "state": s,
                "portrait_url": prog["portrait_url"],
                "tool_result": {"ok": False, "error": res["error"]},
            }
        out = {
            "state": s,
            "portrait_url": res["prog"]["portrait_url"],
            "tool_result": {
                **_build_status_payload(s, res["prog"]),
                "action": "set_name",
                "event": res["event"],
                "stage_changed": res["prog"]["stage_changed"],
            },
        }
        if res["prog"]["append_markdown"]:
            out["append_markdown"] = res["prog"]["append_markdown"]
        return out

    if action == "pass_day":
        apply_day_rollover(s, 1)
        prog = evaluate_progression(s)
        out = {
            "state": s,
            "portrait_url": prog["portrait_url"],
            "tool_result": {
                **_build_status_payload(s, prog),
                "action": "pass_day",
                "event": f"Advanced to Day {s['day']} (Neglect {s['neglect_days']}).",
                "stage_changed": prog["stage_changed"],
            },
        }
        if prog["append_markdown"]:
            out["append_markdown"] = prog["append_markdown"]
        return out

    prog = evaluate_progression(s)
    return {
        "state": s,
        "portrait_url": prog["portrait_url"],
        "tool_result": {"ok": False, "error": f"Unsupported action: {action}"},
    }


def on_after_generate(state, ctx):
    ctx = ctx if isinstance(ctx, dict) else {}
    s = ensure_state_shape(state)

    turn_ledger = ctx.get("turnLedger") if isinstance(ctx.get("turnLedger"), dict) else {}
    pre_turn = turn_ledger.get("handledInPreTurn") if isinstance(turn_ledger.get("handledInPreTurn"), dict) else {}
    tool_calls = turn_ledger.get("handledInToolCall") if isinstance(turn_ledger.get("handledInToolCall"), dict) else {}
    already_handled = bool(pre_turn.get(SCRIPT_ID) or tool_calls.get(SCRIPT_ID))

    if not already_handled:
        assistant_msg = str(ctx.get("assistantMessage") or "")
        if re.search(r"\b(stoke|stoked|tend|tended|embers|firewood|hearthfire)\b", assistant_msg, re.IGNORECASE):
            s["warmth"] = _clamp(s["warmth"] + 5, 0, 100)
            s["trust"] = _clamp(s["trust"] + 1, 0, 100)
            s["cared_today"] = True
        elif re.search(r"\b(comfort|comforted|reassure|reassured|embrace|embraced|gift)\b", assistant_msg, re.IGNORECASE):
            s["warmth"] = _clamp(s["warmth"] + 2, 0, 100)
            s["trust"] = _clamp(s["trust"] + 3, 0, 100)
            s["cared_today"] = True
        else:
            s["warmth"] = _clamp(s["warmth"] - 2, 0, 100)

    prog = evaluate_progression(s)
    out = {"state": s, "portrait_url": prog["portrait_url"]}
    if prog["append_markdown"]:
        out["append_markdown"] = prog["append_markdown"]
    return out


def render_memo(state, ctx):
    s = ensure_state_shape(state)
    pills = [s["stage"], f"Day {s['day']}"]
    if s["cared_today"]:
        pills.append("Cared Today")
    if s["neglect_days"] > 0:
        pills.append(f"Neglect {s['neglect_days']}d")
    if s["warmth"] >= 70:
        pills.append("Cozy Hearth")
    elif s["warmth"] <= 20:
        pills.append("Dying Embers")
    else:
        pills.append("Steady Flame")

    return "\n".join([
        f"Companion: {s['name']}",
        f"Status: ((PILLS)) {', '.join(pills)}",
        f"Warmth: ((BAR)) {s['warmth']}/100",
        f"Trust: ((BARGREEN)) {s['trust']}/100",
    ])
